def factorial(n, p):
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % p
    return result

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

def mod_inverse(a, p):
    gcd, x, _ = extended_gcd(a, p)
    if gcd != 1:
        raise ValueError("Modular inverse does not exist")
    else:
        return x % p

def nCr_mod_p(n, r, p):
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1
    num = factorial(n, p)
    denom = (factorial(r, p) * factorial(n - r, p)) % p
    return (num * mod_inverse(denom, p)) % p

